ee:variables.ee:set-variable:
%dw 2.0
import fileName from dwl::report
output application/java
var day = vars.ctx.reportDate
var name = fileName(vars.ctx.entityCode, vars.ctx.reportType, vars.ctx.reportDate, vars.ctx.sequenceNumber, ".csv")
var summary = fileName(vars.ctx.entityCode, vars.ctx.reportType, vars.ctx.reportDate, vars.ctx.sequenceNumber, "_summary.html")
---
{
  details:    vars.outDir ++ "/work/" ++ vars.runId ++ ".details.part",
  submission: vars.outDir ++ "/" ++ day ++ "/" ++ name,
  summary:    vars.outDir ++ "/" ++ day ++ "/" ++ summary,
  archiveDir: p('file.archiveDir') ++ "/" ++ day ++ "/" ++ vars.runId
}

%dw 2.0
output application/java
---
{
  more: true, serial: 0, total: 0, customers: {}, warnings: [], preview: [],
  cursor: { afterFlaggedAt: "1970-01-02 00:00:00", afterTransactionId: "", afterFlagCode: "" }
}

set-variable.value:
#[output application/java --- {
                        path: '/flags',
                        query: {
                          periodStart: vars.ctx.periodStart, periodEnd: vars.ctx.periodEnd,
                          mode: vars.flagMode, runId: vars.flagRunId default '',
                          afterFlaggedAt: vars.ext.cursor.afterFlaggedAt,
                          afterTransactionId: vars.ext.cursor.afterTransactionId,
                          afterFlagCode: vars.ext.cursor.afterFlagCode,
                          limit: p('flags.pageSize')
                        } }]

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var e = vars.expected
var x = { recordCount: vars.ext.serial, totalAmount: vars.ext.total, customerCount: sizeOf(keysOf(vars.ext.customers)) }
---
{
  ok: (x.recordCount == e.recordCount) and (x.totalAmount == e.totalAmount)
      and (x.customerCount == e.customerCount) and (not vars.ext.more),
  extracted: x,
  expected: { recordCount: e.recordCount, totalAmount: e.totalAmount, customerCount: e.customerCount }
}
